const getRepoIDByPathForUser = `-- name: GetRepoIDByPathForUser :one
SELECT r.id
FROM repos r
JOIN forge_connections c ON c.id = r.connection_id
WHERE r.path_with_namespace = $1 AND c.user_id = $2
`

type GetRepoIDByPathForUserParams struct {
	Path   string    `json:"path"`
	UserID uuid.UUID `json:"user_id"`
}

// Resolve a repo's internal id from its path_with_namespace, scoped to the owning
// user (a repo belongs to a user via its forge connection). The worker's propose_issue
// tool sends the human-readable repo path — it never sees internal UUIDs (Decision 7)
// — so the proposal endpoint resolves it here with the SAME ownership rule as
// GetRepoForUser, just keyed by path. No row = unknown path, or not this user's repo.
func (q *Queries) GetRepoIDByPathForUser(ctx context.Context, arg GetRepoIDByPathForUserParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, getRepoIDByPathForUser, arg.Path, arg.UserID)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

const listChatRunsForUser = `-- name: ListChatRunsForUser :many
SELECT id, title, status, resume_of_run_id, created_at, updated_at, turn_count, last_message_at FROM (
    SELECT r.id, r.title, r.status, r.resume_of_run_id, r.created_at, r.updated_at,
           (SELECT count(*) FROM run_user_inputs i WHERE i.run_id = r.id AND i.kind = 'follow_up') AS turn_count,
           (SELECT max(m.created_at) FROM run_messages m WHERE m.run_id = r.id)::timestamptz AS last_message_at
    FROM runs r
    WHERE r.user_id = $1 AND r.kind = 'chat'
) chat
ORDER BY COALESCE(chat.last_message_at, chat.created_at) DESC
LIMIT 200
`

type ListChatRunsForUserRow struct {
	ID            uuid.UUID          `json:"id"`
	Title         pgtype.Text        `json:"title"`
	Status        string             `json:"status"`
	ResumeOfRunID pgtype.UUID        `json:"resume_of_run_id"`
	CreatedAt     pgtype.Timestamptz `json:"created_at"`
	UpdatedAt     pgtype.Timestamptz `json:"updated_at"`
	TurnCount     int64              `json:"turn_count"`
	LastMessageAt pgtype.Timestamptz `json:"last_message_at"`
}

// The user's chat conversations for the Chat page's conversation list, ordered by
// LAST ACTIVITY (the list renders and sorts on it). Each row carries turn_count (the
// persisted follow_up inputs, i.e. user turns incl. the seeded first message) and
// last_message_at (the newest run_message time, NULL until the worker emits one) via
// scalar subqueries — no repo join (a chat has no repo). A conversation with no
// messages yet falls back to its created_at for ordering, so a just-created chat
// still sorts to the top. Wrapped in a subselect so the ORDER BY can reference the
// computed last_message_at.
func (q *Queries) ListChatRunsForUser(ctx context.Context, userID uuid.UUID) ([]ListChatRunsForUserRow, error) {
	rows, err := q.db.Query(ctx, listChatRunsForUser, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListChatRunsForUserRow{}
	for rows.Next() {
		var i ListChatRunsForUserRow
		if err := rows.Scan(
			&i.ID,
			&i.Title,
			&i.Status,
			&i.ResumeOfRunID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.TurnCount,
			&i.LastMessageAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const markProposalConfirmed = `-- name: MarkProposalConfirmed :one
UPDATE issue_proposals SET status = 'confirmed', created_issue_iid = $1, resolved_at = now(), confirming_since = NULL
WHERE id = $2 AND status = 'confirming'
RETURNING id, run_id, repo_id, title, description, labels, status, created_issue_iid, created_at, resolved_at, confirming_since
`

type MarkProposalConfirmedParams struct {
	CreatedIssueIid pgtype.Int8 `json:"created_issue_iid"`
	ID              uuid.UUID   `json:"id"`
}

// Claim-first confirmation, phase 2: stamp the created issue iid AFTER the forge
// CreateIssue succeeded. Guarded on status='confirming' (the state ClaimProposalForConfirm
// left it in), so it only ever settles a proposal this same flow claimed. Clears the
// transient confirming_since marker.
func (q *Queries) MarkProposalConfirmed(ctx context.Context, arg MarkProposalConfirmedParams) (IssueProposal, error) {
	row := q.db.QueryRow(ctx, markProposalConfirmed, arg.CreatedIssueIid, arg.ID)
	var i IssueProposal
	err := row.Scan(
		&i.ID,
		&i.RunID,
		&i.RepoID,
		&i.Title,
		&i.Description,
		&i.Labels,
		&i.Status,
		&i.CreatedIssueIid,
		&i.CreatedAt,
		&i.ResolvedAt,
		&i.ConfirmingSince,
	)
	return i, err
}

const markProposalDismissed = `-- name: MarkProposalDismissed :one
UPDATE issue_proposals SET status = 'dismissed', resolved_at = now()
WHERE id = $1 AND status = 'pending'
RETURNING id, run_id, repo_id, title, description, labels, status, created_issue_iid, created_at, resolved_at, confirming_since
`

// Dismiss a proposal. Status-only, never a forge write (Decision 8) — dismissing
// provably writes nothing to the forge. Guarded on status='pending' for idempotency.
func (q *Queries) MarkProposalDismissed(ctx context.Context, id uuid.UUID) (IssueProposal, error) {
	row := q.db.QueryRow(ctx, markProposalDismissed, id)
	var i IssueProposal
	err := row.Scan(
		&i.ID,
		&i.RunID,
		&i.RepoID,
		&i.Title,
		&i.Description,
		&i.Labels,
		&i.Status,
		&i.CreatedIssueIid,
		&i.CreatedAt,
		&i.ResolvedAt,
		&i.ConfirmingSince,
	)
	return i, err
}

const revertProposalToPending = `-- name: RevertProposalToPending :execrows
UPDATE issue_proposals SET status = 'pending', confirming_since = NULL
WHERE id = $1 AND status = 'confirming'
`

// Claim-first confirmation, failure path: return a claimed proposal to 'pending' when
// the forge CreateIssue (or a step after the claim) failed, so the user can retry or
// dismiss it. Guarded on status='confirming' so it can only undo an in-flight claim.
// Clears confirming_since (no longer in flight).
func (q *Queries) RevertProposalToPending(ctx context.Context, id uuid.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, revertProposalToPending, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const sweepIdleChatRuns = `-- name: SweepIdleChatRuns :many
UPDATE runs SET status = 'completed', finished_at = now(), updated_at = now()
WHERE kind = 'chat'
  AND status IN ('claimed', 'running')
  AND id IN (
      SELECT r.id FROM runs r
      JOIN run_messages m ON m.run_id = r.id
      WHERE r.kind = 'chat' AND r.status IN ('claimed', 'running')
      GROUP BY r.id
      HAVING max(m.created_at) < $1
  )
RETURNING id, user_id, status
`

type SweepIdleChatRunsRow struct {
	ID     uuid.UUID `json:"id"`
	UserID uuid.UUID `json:"user_id"`
	Status string    `json:"status"`
}

// Server-side idle backstop (Decision 3a): a chat run whose most recent run_message
// is older than the idle cutoff → completed. The worker itself completes an idle
// chat after WORKER_CHAT_IDLE_TIMEOUT; this is the not-trusting-the-worker sweep for
// a worker that stays alive (so the stale-worker sweeps never fire) but fails to
// complete an idle conversation. Only runs with at least one message are eligible,
// so a queued chat waiting for a worker (no messages yet) is never reaped — a queued
// run sits indefinitely by design. RETURNING drives the same broadcast fan-out as
// the other sweeps.
func (q *Queries) SweepIdleChatRuns(ctx context.Context, cutoff pgtype.Timestamptz) ([]SweepIdleChatRunsRow, error) {
	rows, err := q.db.Query(ctx, sweepIdleChatRuns, cutoff)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SweepIdleChatRunsRow{}
	for rows.Next() {
		var i SweepIdleChatRunsRow
		if err := rows.Scan(&i.ID, &i.UserID, &i.Status); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const sweepStuckConfirmingProposals = `-- name: SweepStuckConfirmingProposals :many
UPDATE issue_proposals SET status = 'pending', confirming_since = NULL
WHERE status = 'confirming' AND confirming_since IS NOT NULL AND confirming_since < $1
RETURNING id
`

// Recover proposals stranded in 'confirming' by a confirm handler that was killed
// after the claim committed but before it settled/reverted (the crash window). Any
// 'confirming' row older than the cutoff (now - PROPOSAL_CONFIRM_STUCK_TIMEOUT) goes
// back to pending so the user can retry or dismiss it — the not-trusting-the-process
// backstop, mirroring SweepClaimedNeverStarted for stale run claims. The cutoff sits
// well above the forge HTTP timeout, so a legitimately in-flight confirm is never
// reaped. RETURNING id for the sweep's count/log.
func (q *Queries) SweepStuckConfirmingProposals(ctx context.Context, cutoff pgtype.Timestamptz) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, sweepStuckConfirmingProposals, cutoff)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
